export {countryBatches,stateIdentities};
export function buildRegionalAssets(T,{land,name:state,type,ground,explorer}){
 const countryMode=type==='country',profile=countryBatches[state];
 const identity=countryMode?{style:profile?.style||'forest',cues:profile?.features||['Wooded landscape','Quiet waterway']}:stateIdentities[state];
 const style=identity.style,stateLake=null,interactions={time:0};
 const walking={ground,avatar:explorer,canOccupy:(x,z)=>!!ground(x,z)};
 const scenery=countryMode?{group:new T.Group(),placed:0,features:[]}:buildLandScenery(T,{land,state,style,ground,spawn:explorer.position});
 if(countryMode)land.add(scenery.group);
  const landmarks=countryMode&&countryBatches[state]?buildBatchScenery(T,{land,ground:walking.ground,spawn:walking.avatar.position,profile:countryBatches[state]}):countryMode&&state==='Laos'?buildLaosScenery(T,{land,ground:walking.ground,spawn:walking.avatar.position}):countryMode&&state==='Vietnam'?buildVietnamScenery(T,{land,ground:walking.ground,spawn:walking.avatar.position}):countryMode&&state==='Thailand'?buildThailandScenery(T,{land,ground:walking.ground,spawn:walking.avatar.position}):countryMode&&state==='China'?buildChinaScenery(T,{land,ground:walking.ground,spawn:walking.avatar.position}):countryMode&&state==='Japan'?buildJapanScenery(T,{land,ground:walking.ground,spawn:walking.avatar.position}):!countryMode&&state==='Wisconsin'?buildWisconsinLandmarks(T,{land,ground:walking.ground}):state==='California'?buildCaliforniaScenery(T,{land,ground:walking.ground}):state==='Utah'?buildUtahScenery(T,{land,ground:walking.ground}):state==='Idaho'?buildIdahoScenery(T,{land,ground:walking.ground,lakeCenter:stateLake}):state==='Oregon'?buildOregonScenery(T,{land,ground:walking.ground,lakeCenter:stateLake}):state==='Washington'?buildWashingtonScenery(T,{land,ground:walking.ground}):buildRegionalScenery(T,{land,ground:walking.ground,style,cues:identity.cues,spawn:walking.avatar.position});
  const housingObstacles=[...(landmarks?.obstacles||[]),...((countryBatches[state]?.theme==='river-homes'?[]:landmarks?.waterBounds||[]).map(b=>({x:(b.min.x+b.max.x)/2,z:(b.min.z+b.max.z)/2,halfX:(b.max.x-b.min.x)/2+.35,halfZ:(b.max.z-b.min.z)/2+.35})))];
  const neighborhood=countryMode&&countryBatches[state]?buildBatchHomes(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles,profile:countryBatches[state]}):countryMode&&state==='Laos'?buildLaosNeighborhood(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles}):countryMode&&state==='Thailand'?buildThailandNeighborhood(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles}):countryMode&&state==='Vietnam'?buildVietnamNeighborhood(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles}):countryMode&&state==='China'?buildChinaNeighborhood(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles}):countryMode&&state==='South Korea'?buildKoreaNeighborhood(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles}):countryMode&&state==='Japan'?buildJapanNeighborhood(T,{land,ground:walking.ground,spawn:walking.avatar.position,occupied:housingObstacles}):!countryMode&&state==='Wisconsin'?buildWisconsinNeighborhood(T,{land,ground:walking.ground}):null;
  if(countryMode&&countryBatches[state]?.batch===2&&neighborhood)addSparseFieldFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 if(countryMode&&countryBatches[state]?.batch>=29&&countryBatches[state]?.batch<=55&&neighborhood)addAfricaFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 if(countryMode&&countryBatches[state]?.batch>=23&&countryBatches[state]?.batch<=28&&neighborhood)addAfricaFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 if(countryMode&&countryBatches[state]?.batch>=17&&countryBatches[state]?.batch<=22&&neighborhood)addNextThirtyFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 if(countryMode&&[15,16].includes(countryBatches[state]?.batch)&&neighborhood)addCaucasusFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 if(countryMode&&countryBatches[state]?.batch===14&&neighborhood)addCentralAsiaFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 if(countryMode&&countryBatches[state]?.batch===13&&neighborhood)addSouthAsiaFlowers(T,{land,ground:walking.ground,profile:countryBatches[state],neighborhood,landmarks});
 const obstacles=[...(neighborhood?.obstacles||[]),...(landmarks?.obstacles||[])];
 // Tree trunks, rather than their crowns, obstruct walking.
 for(const tree of scenery.group.children)if(tree.userData.species)obstacles.push({x:tree.position.x,z:tree.position.z,halfX:.65,halfZ:.65});
 walking.canOccupy=(x,z)=>!!ground(x,z)&&!obstacles.some(o=>Math.abs(x-o.x)<o.halfX+.6&&Math.abs(z-o.z)<o.halfZ+.6);
  const wildlife=countryMode&&countryBatches[state]?buildLaosWildlife(T,{land,ground:walking.ground,canOccupy:(x,z)=>walking.canOccupy(x,z)&&!(landmarks?.obstacles||[]).some(o=>Math.abs(x-o.x)<o.halfX+.6&&Math.abs(z-o.z)<o.halfZ+.6),explorer:walking.avatar,waterBounds:landmarks.waterBounds,roster:countryBatches[state].roster,regionName:state,getInteractionTime:()=>interactions.time}):countryMode&&state==='Laos'?buildLaosWildlife(T,{land,ground:walking.ground,canOccupy:(x,z)=>walking.canOccupy(x,z)&&!(landmarks?.obstacles||[]).some(o=>Math.abs(x-o.x)<o.halfX+.6&&Math.abs(z-o.z)<o.halfZ+.6),explorer:walking.avatar,waterBounds:landmarks.waterBounds,getInteractionTime:()=>interactions.time}):countryMode&&state==='Vietnam'?buildVietnamWildlife(T,{land,ground:walking.ground,canOccupy:(x,z)=>walking.canOccupy(x,z)&&!(landmarks?.obstacles||[]).some(o=>Math.abs(x-o.x)<o.halfX+.6&&Math.abs(z-o.z)<o.halfZ+.6),explorer:walking.avatar,getInteractionTime:()=>interactions.time}):countryMode&&state==='Thailand'?buildThailandWildlife(T,{land,ground:walking.ground,canOccupy:(x,z)=>walking.canOccupy(x,z)&&!(landmarks?.obstacles||[]).some(o=>Math.abs(x-o.x)<o.halfX+.6&&Math.abs(z-o.z)<o.halfZ+.6),explorer:walking.avatar}):!countryMode&&state==='Wisconsin'?buildWisconsinWildlife(T,{land,ground:walking.ground,canOccupy:walking.canOccupy,scenery,explorer:walking.avatar}):null;
 obstacles.push(...(wildlife?.habitatObstacles||[]));
 return {scenery,landmarks,homes:neighborhood,wildlife,obstacles,style,get interactionTime(){return interactions.time;},update(dt){interactions.time+=dt;wildlife?.update(dt);}};
}
